    internal static class OnityWhenAnyTuple<T1, T2>
    {
        /// <summary>
        /// Native single-consumer source of one pending output on the array <c>WhenAny</c> base, which
        /// picks the winner, keeps observing the losers and returns the source to its pool.
        /// </summary>
        internal sealed class Source :
            OnityWhenAnyArrayTaskSourceBase<(int, T1, T2)>,
            IOnityPooledRunner<Source>,
            IOnityCompositionInputs
        {
            private const int k_inputCount = 2;

            private static OnityRunnerPool<Source> s_pool;

            private Source m_nextPooled;
            private OnityTask<T1> m_task1;
            private OnityTask<T2> m_task2;

            private Source() : base(k_inputCount)
            {
            }

            ref Source IOnityPooledRunner<Source>.NextPooled => ref m_nextPooled;

            internal static Source Rent(
                OnityTask<T1> task1,
                OnityTask<T2> task2,
                bool validateInputs)
            {
                // A contended rent allocates instead of waiting.
                if (!s_pool.TryPop(out Source source))
                {
                    source = new Source();
                }

                source.m_task1 = task1;
                source.m_task2 = task2;
                if (validateInputs)
                {
                    int duplicate = OnityTaskComposition.FindDuplicateInput(source, k_inputCount);
                    if (duplicate >= 0)
                    {
                        source.ClearInputs(k_inputCount);
                        source.ReturnToPool();
                        OnityTaskComposition.ThrowDuplicateInput(OnityTaskComposition.k_whenAny, duplicate);
                    }
                }

                source.Initialize(k_inputCount);
                return source;
            }

            public bool TryGetInputIdentity(int index, out OnityWhenAnyInputIdentity identity)
            {
                switch (index)
                {
                    case 0:
                        return m_task1.TryGetWhenAnyIdentity(out identity);
                    default:
                        return m_task2.TryGetWhenAnyIdentity(out identity);
                }
            }

            protected override void RegisterInput(int index, Action callback)
            {
                switch (index)
                {
                    case 0:
                        m_task1.RegisterWhenAnyObserver(callback);
                        return;
                    default:
                        m_task2.RegisterWhenAnyObserver(callback);
                        return;
                }
            }

            protected override OnityTaskSourceStatus ReadOutcome(
                int index,
                out (int, T1, T2) result,
                out Exception fault,
                out CancellationToken cancellationToken)
            {
                result = default;
                result.Item1 = index;
                switch (index)
                {
                    case 0:
                        return m_task1.ReadWhenAnyOutcome(out result.Item2, out fault, out cancellationToken);
                    default:
                        return m_task2.ReadWhenAnyOutcome(out result.Item3, out fault, out cancellationToken);
                }
            }

            protected override void ClearInput(int index)
            {
                switch (index)
                {
                    case 0:
                        m_task1 = default;
                        return;
                    default:
                        m_task2 = default;
                        return;
                }
            }

            protected override void ClearInputs(int count)
            {
                m_task1 = default;
                m_task2 = default;
            }

            protected override void ReturnToPool()
            {
                // A contended or full return lets the source be collected.
                s_pool.TryPush(this, OnityTaskSettings.s_sourcePoolCapacity);
            }
        }
    }

