                        return m_task13.ReadWhenAnyOutcome(out result.Item14, out fault, out cancellationToken);
                    case 13:
                        return m_task14.ReadWhenAnyOutcome(out result.Item15, out fault, out cancellationToken);
                    default:
                        return m_task15.ReadWhenAnyOutcome(out result.Item16, out fault, out cancellationToken);
                }
            }

            protected override void ClearInput(int index)
            {
                switch (index)
                {
                    case 0:
                        m_task1 = default;
                        return;
                    case 1:
                        m_task2 = default;
                        return;
                    case 2:
                        m_task3 = default;
                        return;
                    case 3:
                        m_task4 = default;
                        return;
                    case 4:
                        m_task5 = default;
                        return;
                    case 5:
                        m_task6 = default;
                        return;
                    case 6:
                        m_task7 = default;
                        return;
                    case 7:
                        m_task8 = default;
                        return;
                    case 8:
                        m_task9 = default;
                        return;
                    case 9:
                        m_task10 = default;
                        return;
                    case 10:
                        m_task11 = default;
                        return;
                    case 11:
                        m_task12 = default;
                        return;
                    case 12:
                        m_task13 = default;
                        return;
                    case 13:
                        m_task14 = default;
                        return;
                    default:
                        m_task15 = default;
                        return;
                }
            }

            protected override void ClearInputs(int count)
            {
                m_task1 = default;
                m_task2 = default;
                m_task3 = default;
                m_task4 = default;
                m_task5 = default;
                m_task6 = default;
                m_task7 = default;
                m_task8 = default;
                m_task9 = default;
                m_task10 = default;
                m_task11 = default;
                m_task12 = default;
                m_task13 = default;
                m_task14 = default;
                m_task15 = default;
            }

            protected override void ReturnToPool()
            {
                // A contended or full return lets the source be collected.
                s_pool.TryPush(this, OnityTaskSettings.s_sourcePoolCapacity);
            }
        }
